<?php
include '../includes/auth.php';
include '../db.php';
header('Location: product_import.php');
exit;
$msg=''; $msgType='';

if (isset($_POST['save_supplier'])) {
    $id=(int)($_POST['supplier_id']??0); $name=trim($_POST['supplier_name']??''); $code=trim($_POST['supplier_code']??'');
    $contact=trim($_POST['contact_person']??''); $phone=trim($_POST['phone']??''); $email=trim($_POST['email']??''); $address=trim($_POST['address']??'');
    $opening=max(0,(float)($_POST['opening_balance']??0)); $status=(int)($_POST['status']??1);
    if ($name==='') { $msg='Supplier name is required.'; $msgType='error'; }
    else {
        try {
            if ($id>0) { $s=$conn->prepare("UPDATE suppliers SET supplier_code=NULLIF(?,''),supplier_name=?,contact_person=?,phone=?,email=?,address=?,opening_balance=?,status=? WHERE supplier_id=?"); $s->bind_param('ssssssdii',$code,$name,$contact,$phone,$email,$address,$opening,$status,$id); }
            else { $s=$conn->prepare("INSERT INTO suppliers (supplier_code,supplier_name,contact_person,phone,email,address,opening_balance,status) VALUES (NULLIF(?,''),?,?,?,?,?,?,?)"); $s->bind_param('ssssssdi',$code,$name,$contact,$phone,$email,$address,$opening,$status); }
            $s->execute(); $s->close(); $msg='Supplier saved successfully.'; $msgType='success';
        } catch(Throwable $e) { $msg=$e->getCode()===1062?'Supplier code already exists.':$e->getMessage(); $msgType='error'; }
    }
}
$edit=null; if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$q=$conn->prepare("SELECT * FROM suppliers WHERE supplier_id=?");$q->bind_param('i',$id);$q->execute();$edit=$q->get_result()->fetch_assoc();$q->close();}
$suppliers=$conn->query("SELECT s.*,COALESCE(SUM(CASE WHEN p.status<>'cancelled' THEN p.total_amount-p.paid_amount ELSE 0 END),0)+s.opening_balance balance,COUNT(p.purchase_id) purchase_count FROM suppliers s LEFT JOIN purchases p ON p.supplier_id=s.supplier_id GROUP BY s.supplier_id ORDER BY s.supplier_name");
$summary=$conn->query("SELECT COUNT(*) total,COALESCE(SUM(status=1),0) active,COALESCE(SUM(opening_balance),0) opening FROM suppliers")->fetch_assoc();
$payable=$conn->query("SELECT COALESCE(SUM(total_amount-paid_amount),0) v FROM purchases WHERE status<>'cancelled'")->fetch_assoc()['v'];
?>
