<?php include 'shared_nav.php'; ?><main class="main"><?php include 'shared_topbar.php'; ?><div class="content">
<div class="page-header"><div><h1 class="page-title-h"><i class="fa-solid fa-truck-field"></i> Suppliers</h1><p class="page-sub">Supplier contacts, purchase history and outstanding balances</p></div><div class="quick-links"><a class="btn-primary" href="purchases.php?new=1"><i class="fa-solid fa-cart-flatbed"></i> New Purchase</a></div></div>
<?php if($msg):?><div class="alert <?php echo $msgType;?>"><?php echo htmlspecialchars($msg);?></div><?php endif;?>
<div class="erp-stats"><div class="erp-stat"><span>Total Suppliers</span><strong><?php echo (int)$summary['total'];?></strong></div><div class="erp-stat green"><span>Active Suppliers</span><strong><?php echo (int)$summary['active'];?></strong></div><div class="erp-stat amber"><span>Total Payable</span><strong>Rs. <?php echo number_format((float)$payable,2);?></strong></div><div class="erp-stat"><span>Opening Balances</span><strong>Rs. <?php echo number_format((float)$summary['opening'],2);?></strong></div></div>
<div class="erp-grid"><section class="card"><div class="card-head"><h4><i class="fa-solid fa-address-card"></i> <?php echo $edit?'Edit':'Add';?> Supplier</h4></div><form method="post" class="erp-form"><input type="hidden" name="supplier_id" value="<?php echo (int)($edit['supplier_id']??0);?>"><div class="form-grid">
<div class="field"><label>Supplier Code</label><input class="inp" name="supplier_code" value="<?php echo htmlspecialchars($edit['supplier_code']??'');?>" placeholder="SUP-001"></div><div class="field"><label>Status</label><select class="inp" name="status"><option value="1">Active</option><option value="0" <?php echo isset($edit)&&!(int)$edit['status']?'selected':'';?>>Inactive</option></select></div>
<div class="field full"><label>Supplier Name *</label><input class="inp" name="supplier_name" required value="<?php echo htmlspecialchars($edit['supplier_name']??'');?>"></div><div class="field full"><label>Contact Person</label><input class="inp" name="contact_person" value="<?php echo htmlspecialchars($edit['contact_person']??'');?>"></div><div class="field"><label>Phone</label><input class="inp" name="phone" value="<?php echo htmlspecialchars($edit['phone']??'');?>"></div><div class="field"><label>Email</label><input class="inp" type="email" name="email" value="<?php echo htmlspecialchars($edit['email']??'');?>"></div><div class="field full"><label>Address</label><textarea class="inp" name="address"><?php echo htmlspecialchars($edit['address']??'');?></textarea></div><div class="field full"><label>Opening Payable Balance (Rs.)</label><input class="inp" type="number" min="0" step="0.01" name="opening_balance" value="<?php echo htmlspecialchars($edit['opening_balance']??'0');?>"></div></div><div class="actions"><button class="btn-primary" name="save_supplier"><i class="fa-solid fa-floppy-disk"></i> Save Supplier</button><?php if($edit):?><a class="btn-secondary" href="suppliers.php">Cancel</a><?php endif;?></div></form></section>
<section class="card table-card-full"><div class="card-head"><h4><i class="fa-solid fa-list"></i> Supplier Directory</h4><span class="count-badge"><?php echo (int)$summary['total'];?> suppliers</span></div><div class="tbl-wrap"><table><thead><tr><th>Supplier</th><th>Contact</th><th>Purchases</th><th>Balance</th><th>Status</th><th>Action</th></tr></thead><tbody><?php while($s=$suppliers->fetch_assoc()):?><tr><td><strong><?php echo htmlspecialchars($s['supplier_name']);?></strong><div class="muted"><?php echo htmlspecialchars($s['supplier_code']?:'No code');?></div></td><td><?php echo htmlspecialchars($s['phone']?:'-');?><div class="muted"><?php echo htmlspecialchars($s['email']?:'');?></div></td><td><?php echo (int)$s['purchase_count'];?></td><td class="money">Rs. <?php echo number_format((float)$s['balance'],2);?></td><td><span class="status-pill <?php echo $s['status']?'active':'cancelled';?>"><?php echo $s['status']?'Active':'Inactive';?></span></td><td><div class="table-actions"><a class="btn-small" href="?edit=<?php echo (int)$s['supplier_id'];?>"><i class="fa-solid fa-pen"></i> Edit</a><a class="btn-small" href="purchases.php?supplier=<?php echo (int)$s['supplier_id'];?>"><i class="fa-solid fa-clock-rotate-left"></i> Purchases</a></div></td></tr><?php endwhile;?></tbody></table></div></section></div>
</div></main></body></html>
